 {revoke&&<section className="data-card cap-detail"><b>{t('Hủy xác nhận','取消確認','Revoke confirmation')} · {label(week)} · Line {selected.join(', ')}</b><label>{t('Lý do','原因','Reason')}<input value={reason} onChange={e=>setReason(e.target.value)}/></label><FeedbackActionButton disabled={busy||!rights.revoke||!reason.trim()} disabledExplanation={!rights.revoke ? "Bạn không có quyền hủy xác nhận." : busy ? "Đang xử lý. Vui lòng chờ hoàn tất rồi thử lại." : "Nhập lý do hủy xác nhận trước."} onClick={()=>run('revoke')}>{t('Có — Hủy xác nhận','是 — 取消確認','Yes — revoke')}</FeedbackActionButton><FeedbackActionButton disabled={busy} disabledExplanation={"Đang xử lý. Vui lòng chờ hoàn tất rồi thử lại."} onClick={()=>setRevoke(false)}>{t('Không','否','No')}</FeedbackActionButton></section>}
 {view==='calendar'&&<>{showRules&&<p className="cap-units">{t('Bản đã xác nhận nhưng chưa đồng bộ KHSX: được Hủy xác nhận để sửa. Bản đã đồng bộ đang chờ phản hồi: vẫn khóa. Bản được KHSX đồng ý: vào Tổng hợp Capacity gửi Yêu cầu điều chỉnh → KHSX đồng ý mới mở lịch → QLSX sửa, lưu, xác nhận và đồng bộ → KHSX đồng ý Capacity mới. Áp dụng cả Admin. Khi chờ, tiếp tục dùng Capacity đã duyệt gần nhất.','已確認但尚未同步的版本可取消確認修改；同步待審期間鎖定。計畫已核准者須在產能彙總申請並經同意才可修改，重新確認同步後再核准；管理員亦須遵守。等待期間使用最近核准產能。','Confirmed but unsynced versions can be unconfirmed for editing. Synced versions stay locked pending review. Approved versions require an adjustment request in Capacity summary and Planning approval, then confirmation, sync and reapproval. Applies to Admin too. Keep the last approved capacity while waiting.')}</p>}{calendarRow?.input.dailySchedule?<><CapacityDailyEditor key={`${week}-${calendarLine}`} week={week} row={calendarRow} savedRevision={state?.revision} employees={state?.employees||[]} disabled={calendarLocked} factorDisabled={!rights.factor} t={t} locale={lang} onError={setError} onTransfer={transfer} onTransferMany={transferMany} onRemoveTransfer={removeTransfer} showRules={showRules} onChange={input=>{setRows(list=>list.map(r=>r.line===calendarLine?{...r,input}:r));setSelected(s=>Array.from(new Set([...s,calendarLine])));setDirty(true);}}/><section className="data-card cap-detail cap-available"><b>{t('Giờ khả dụng dự tính','預估工時','Projected available hours')}: {format(result(calendarRow).value?.availableHours)}h</b>{result(calendarRow).error&&<p className="cap-error">{result(calendarRow).error}</p>}</section></>:calendarRow?<section className="data-card cap-detail"><strong>{t('Tuần đã lưu theo bảng Capacity tổng hợp','此週已按彙總產能表保存','Week saved as aggregate Capacity')}</strong><p>{t('Bản tuần này có dữ liệu tổng hợp, nhưng chưa lưu lịch từng ngày và tên nhân viên. Danh sách nhân viên nhập sau đó không tự gán ngược vào tuần cũ. Chọn Quay lại để xem bản đã lưu trong Tổng hợp Capacity.','此週保存了彙總數據，沒有每日排班與員工姓名。後來匯入的員工不會自動加入舊週。點選返回查看彙總資料。','This week has saved aggregate data but no daily schedule or named roster. Employees imported later are not assigned to past weeks automatically. Select Back to view the saved Capacity summary.')}</p></section>:<section className="data-card cap-detail">{t('Không có dữ liệu Capacity cho Line này trong tuần đã chọn.','所選週次沒有此產線的產能資料。','No Capacity data for this line in the selected week.')}</section>}</>}
